/** Browser modules stay readable and independently testable. */
function htmlEditorScript(): string {
  return readFileSync(new URL('./visual-editor.js', import.meta.url), 'utf8').replace('/* CANVAS_STATE_HELPERS */', readFileSync(new URL('./visual-canvas-state.js', import.meta.url), 'utf8')).replace('/* MEDIA_EDITOR_HELPERS */', readFileSync(new URL('./visual-media.js', import.meta.url), 'utf8')).replace('/* GALLERY_EDITOR_HELPERS */', readFileSync(new URL('./visual-gallery.js', import.meta.url), 'utf8')).replace('/* COLUMN_LAYOUT_HELPERS */', readFileSync(new URL('./visual-columns.js', import.meta.url), 'utf8')).replace(/<\/script/gi, '<\\/script')
}

function scriptJson(value: unknown): string {
  return JSON.stringify(value).replace(/</g, '\\u003c').replace(/\u2028/g, '\\u2028').replace(/\u2029/g, '\\u2029')
}
